/* { dg-output "OK" } */

package aaa;

// dup_x2 with a long or double under the top value (its second form): the
// idiom Kawa uses to swap a reference with a double below it.  javac
// doesn't emit it, so the class is assembled by hand (generated by a small
// script; version 49, so it needs no StackMapTable):
//
//   static long f(Object o) {
//      0: lconst_1  1: aload_0
//      2: dup_x2  3: pop               ; o, 1L
//      4: lstore_1  5: ifnull 10
//      8: lload_1  9: lreturn
//     10: lconst_0  11: lreturn
//   }
//
// OpenLDK chose dup_x2's form by the top value's category instead of the
// one below it, and reached past the bottom of the stack.
public class dupx2 extends ClassLoader
{
    private static final byte[] SWAP = new byte[] {
        -54,-2,-70,-66,0,0,0,49,0,8,1,0,14,97,97,97,47,100,117,112,120,50,36,83,119,97,112,7,0,1,1,0,16,106,97,118,97,47,108,97,110,103,47,79,98,106,101,99,116,7,0,3,1,0,4,67,111,100,101,1,0,1,102,1,0,21,40,76,106,97,118,97,47,108,97,110,103,47,79,98,106,101,99,116,59,41,74,0,33,0,2,0,4,0,0,0,0,0,1,0,9,0,6,0,7,0,1,0,5,0,0,0,24,0,4,0,3,0,0,0,12,10,42,91,87,64,-58,0,5,31,-83,9,-83,0,0,0,0,0,0
    };

    protected Class<?> findClass(String name) throws ClassNotFoundException
    {
        if (!name.equals("aaa.dupx2$Swap")) throw new ClassNotFoundException(name);
        return defineClass(name, SWAP, 0, SWAP.length);
    }

    static Object call(Class<?> c, Object o)
    {
        try { return c.getMethod("f", Object.class).invoke(null, o); }
        catch (java.lang.reflect.InvocationTargetException e) { return "escaped: " + e.getCause(); }
        catch (Throwable t) { return "escaped: " + t; }
    }

    public static void main(String[] args) throws Exception
    {
        Class<?> c = new dupx2().loadClass("aaa.dupx2$Swap");
        String result = call(c, "x") + " " + call(c, null);
        System.out.println("1 0".equals(result) ? "OK" : "FAIL: " + result);
    }
}
